// The light scene codec against the REAL firmware code: ui/tests/vectors/lightscene_vectors.json is generated by
// firmware/tools/gen_lightscene_vector.py from km_lightscene.c (nothing is pasted by hand). Regenerate it after any change there.
import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import {
  LS, SRC, OFF, FLAG_BLINK, LightSceneError, cloneScene, decodeScene, defaultScene, encodeScene, ruleProblem, sceneProblem,
} from "../js/core/lightscene_codec.js";
import { crc32 } from "../js/device/config_protocol.js";

const V = JSON.parse(readFileSync(new URL("./vectors/lightscene_vectors.json", import.meta.url), "utf8"));
const hex = (b) => Buffer.from(b).toString("hex");
const bytes = (h) => Uint8Array.from(Buffer.from(h, "hex"));
const seal = (b) => {
  const c = crc32(b.subarray(0, b.length - 4));
  b[b.length - 4] = c & 0xff; b[b.length - 3] = (c >>> 8) & 0xff; b[b.length - 2] = (c >>> 16) & 0xff; b[b.length - 1] = (c >>> 24) & 0xff;
  return b;
};

test("the vector file and the constants agree", () => {
  assert.equal(V.crc_check_123456789, "cbf43926");
  assert.equal(V.max_encoded, LS.maxEncoded);
  assert.equal(150 + 8 * LS.maxRules, LS.maxEncoded);
  assert.equal(LS.keysBytes, 109);
  assert.ok(V.enc.length >= 40 && V.dec.length >= 60 && V.sweep.results.length > 900);
});

test("the default scene is the firmware's default scene and round-trips", () => {
  const d = V.enc.find((c) => c.name === "default");
  const s = defaultScene();
  assert.equal(hex(encodeScene(s)), d.encoded);
  assert.equal(d.encoded.length, 2 * 150);
  assert.deepEqual(decodeScene(bytes(d.encoded)), s);
});

for (const c of V.enc) {
  test(`encode ${c.name}: JS output is byte-identical to the firmware's (or both refuse)`, () => {
    const s = { ...c.model, extra: [] };
    if (c.encoded === null) {
      assert.throws(() => encodeScene(s), LightSceneError, "the firmware refuses this, so must the codec");
      assert.ok(sceneProblem(s));
    } else {
      const out = encodeScene(s);
      assert.equal(hex(out), c.encoded);
      assert.deepEqual(decodeScene(out), s, "decode(encode(x)) == x");
      assert.ok(out.length <= LS.maxEncoded);
    }
  });
}

for (const c of V.dec) {
  test(`decode ${c.name}: JS accepts / refuses like the firmware`, () => {
    const input = bytes(c.input);
    if (c.reencoded === null) {
      assert.throws(() => decodeScene(input), LightSceneError);
    } else {
      const s = decodeScene(input);
      // the firmware forgets unknown optional sections; without them both sides write the same bytes back
      assert.equal(hex(encodeScene({ ...s, extra: [] })), c.reencoded);
      if (s.extra.length > 0) assert.ok(s.extra.every((e) => e.id >= 0x80));
    }
  });
}

test("single-byte changes of a real scene (checksum repaired): same verdict and same canonical bytes as the firmware", () => {
  const base = bytes(V.sweep.base);
  let accepted = 0;
  for (const [pos, v, want] of V.sweep.results) {
    const b = Uint8Array.from(base);
    b[pos] = v;
    seal(b);
    if (want === null) {
      assert.throws(() => decodeScene(b), LightSceneError, `byte ${pos} = ${v}`);
    } else {
      accepted++;
      assert.equal(hex(encodeScene({ ...decodeScene(b), extra: [] })), want, `byte ${pos} = ${v}`);
    }
  }
  assert.ok(accepted > 300);
});

test("unknown optional sections are kept, in order, and written back after the known ones", () => {
  const withExtra = V.dec.find((c) => c.name === "optional_after_known");
  const s = decodeScene(bytes(withExtra.input));
  assert.deepEqual(s.extra.map((e) => e.id), [0x80, 0xf0]);
  assert.equal(hex(s.extra[0].data), Buffer.from("abc").toString("hex"));
  const again = encodeScene(s);
  assert.equal(again.length, 150 + 8 + 4 + 3 + 4 + 0 + 0 - 0);   // one rule (8 bytes), plus the two extra sections
  assert.deepEqual(decodeScene(again), s);
  const dropped = encodeScene({ ...s, extra: [] });
  assert.equal(dropped.length, again.length - 11);
  // extra sections must keep the id order and stay optional
  assert.throws(() => encodeScene({ ...s, extra: [{ id: 0x04, data: new Uint8Array() }] }), LightSceneError);
  assert.throws(() => encodeScene({ ...s, extra: [{ id: 0x90, data: new Uint8Array() }, { id: 0x80, data: new Uint8Array() }] }), LightSceneError);
  assert.throws(() => encodeScene({ ...s, extra: [{ id: 0x80, data: new Uint8Array(1000) }] }), LightSceneError, "over 1024 bytes");
});

test("rule checks are the firmware's", () => {
  const ok = { source: SRC.HOST_CAPS, param: 0, led: 28, flags: OFF.DIM | FLAG_BLINK, color: [255, 0, 0], dim: 30 };
  assert.equal(ruleProblem(ok), null);
  assert.equal(ruleProblem({ ...ok, source: 0 }), "source");
  assert.equal(ruleProblem({ ...ok, source: 9 }), "source");
  assert.equal(ruleProblem({ ...ok, param: 1 }), "param");
  assert.equal(ruleProblem({ ...ok, source: SRC.LAYER, param: 3 }), null);
  assert.equal(ruleProblem({ ...ok, source: SRC.LAYER, param: 4 }), "param");
  assert.equal(ruleProblem({ ...ok, led: 61 }), "led");
  assert.equal(ruleProblem({ ...ok, flags: 8 }), "flags");
  assert.equal(ruleProblem({ ...ok, flags: 3 }), "off_mode");
  assert.equal(ruleProblem({ ...ok, flags: OFF.BLACK, dim: 1 }), "dim");
  assert.equal(ruleProblem({ ...ok, color: [0, 0, 256] }), "field_range");
  assert.equal(ruleProblem({ ...ok, dim: 1.5 }), "field_range");
});

test("cloneScene is a deep copy", () => {
  const s = defaultScene();
  s.rules.push({ source: 2, param: 0, led: 1, flags: 0, color: [1, 2, 3], dim: 0 });
  const c = cloneScene(s);
  c.rules[0].color[0] = 9;
  c.palette[0][0] = 9;
  c.keys[0] = 3;
  assert.equal(s.rules[0].color[0], 1);
  assert.equal(s.palette[0][0], 0);
  assert.equal(s.keys[0], 0);
});

test("decode refuses what is not bytes of a scene", () => {
  assert.throws(() => decodeScene(null), LightSceneError);
  assert.throws(() => decodeScene(new Uint8Array(0)), LightSceneError);
  assert.throws(() => decodeScene(new Uint8Array(1025)), LightSceneError);
});
